import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../models/educational_advisor.dart';
import '../../services/educational_firestore_service.dart';
class ConsultationRequestScreen extends StatefulWidget { const ConsultationRequestScreen({super.key,required this.studentId,required this.advisor});final String studentId;final EducationalAdvisor advisor;@override State<ConsultationRequestScreen> createState()=>_ConsultationRequestScreenState();}
class _ConsultationRequestScreenState extends State<ConsultationRequestScreen>{final subject=TextEditingController();final note=TextEditingController();bool saving=false;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('طلب استشارة مع ${widget.advisor.name}')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[TextField(controller:subject,decoration:const InputDecoration(labelText:'موضوع الاستشارة')),const SizedBox(height:12),TextField(controller:note,maxLines:4,decoration:const InputDecoration(labelText:'ما الذي تحتاج مساعدة فيه؟')),const Spacer(),FilledButton(onPressed:saving?null:()async{if(subject.text.trim().isEmpty)return;setState(()=>saving=true);await context.read<EducationalFirestoreService>().requestConsultation(studentId:widget.studentId,advisorId:widget.advisor.id,subject:subject.text.trim(),note:note.text.trim());if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال طلب الاستشارة.')));Navigator.pop(context);}},child:Text(saving?'جارٍ الإرسال...':'إرسال الطلب'))])));}
